import { Tile } from './tileset'

/**
 * Map format, deliberately close to a Tiled export (`width`, `height`,
 * `tilewidth`, flat layer arrays) so a real `.tmj` could be loaded by reading
 * its layers straight into this shape.
 *
 * ⚠️ This is a wire format: the map is **generated by the server**
 * (`backend/src/world/mapData.ts`) and arrives in `world:welcome`. There is no
 * generator here on purpose — a second one could drift by a tile and make the
 * server reject steps the client believed were legal.
 *
 * Three layers, each rendered differently:
 *  - `ground`  flat, opaque, one tile everywhere
 *  - `overlay` flat, transparent, sits just above the ground (flowers…)
 *  - `objects` upright billboards (trees, bushes, fences)
 */
export type LayerName = 'ground' | 'overlay' | 'objects'

export interface TileLayer {
	name: LayerName
	/** Row-major, `width * height` tile ids. 0 means "nothing here". */
	data: Tile[]
}

/** A building the player can walk into, as the server placed it. */
export interface MapSite {
	id: string
	x: number
	y: number
}

export type CampSite = MapSite

export interface TileMapData {
	width: number
	height: number
	tilewidth: number
	layers: TileLayer[]
	/** Walkable tile a fresh player starts on — the main crossroads. */
	spawn: { x: number; y: number }
	/** The five training camps, placed by the server's generator. */
	camps: CampSite[]
	/** The healing centres, placed and entered the same way. */
	centers: MapSite[]
}

/** The camp standing on a tile, if any. */
export function campAt(map: TileMapData, x: number, y: number): CampSite | null {
	return map.camps?.find((camp) => camp.x === x && camp.y === y) ?? null
}

/** The healing centre standing on a tile, if any. */
export function centerAt(map: TileMapData, x: number, y: number): MapSite | null {
	return map.centers?.find((site) => site.x === x && site.y === y) ?? null
}

export function layerOf(map: TileMapData, name: LayerName): Tile[] {
	return map.layers.find((l) => l.name === name)?.data ?? []
}

export function tileAt(map: TileMapData, name: LayerName, x: number, y: number): Tile {
	if (x < 0 || y < 0 || x >= map.width || y >= map.height) return Tile.Empty
	return layerOf(map, name)[y * map.width + x] ?? Tile.Empty
}
